#pragma once
#include "rinkfit/joint_ceres_bounds.hpp"
#include "rinkfit/joint_manifold.hpp"
#include "rinkfit/joint_recovery_source_capture.hpp"
#include <map>
#include <set>
namespace rinkfit {
namespace runtime_primitive_release_detail_v1 {
struct Dependency {std::filesystem::path path;std::string sha;std::uintmax_t bytes;std::filesystem::file_time_type time;};
inline std::vector<Dependency>&dependencies(){static std::vector<Dependency>v;return v;}
inline void pin(const std::filesystem::path&p,const std::string&sha){for(const auto&d:dependencies())if(d.path==p){if(d.sha!=sha)throw std::runtime_error("runtime primitive source path has conflicting exact hashes");if(d.bytes==std::filesystem::file_size(p)&&d.time==std::filesystem::last_write_time(p))return;break;}const auto n=std::filesystem::file_size(p);const auto t=std::filesystem::last_write_time(p);eventio::verify(p,sha);if(n!=std::filesystem::file_size(p)||t!=std::filesystem::last_write_time(p))throw std::runtime_error("runtime primitive source changed during SHA verification");for(auto&d:dependencies())if(d.path==p){d={p,sha,n,t};return;}dependencies().push_back({p,sha,n,t});}
}
inline void assert_joint_runtime_primitive_release_dependencies_v1(){for(const auto&d:runtime_primitive_release_detail_v1::dependencies())if(!std::filesystem::exists(d.path)||d.bytes!=std::filesystem::file_size(d.path)||d.time!=std::filesystem::last_write_time(d.path))throw std::runtime_error("runtime primitive source support changed: "+d.path.u8string());}
// An inherited constant flag is not evidence of a measured primitive. Release is
// nevertheless explicit, source-instance bound, and excluded from the full S01
// projection dependency closure. This changes only the Ceres runtime policy.
inline eventio::Json apply_joint_runtime_primitive_release_v1(JointALBuilder&b,ceres::Problem&problem,const eventio::Json&cfg){
 using Json=eventio::Json;const char*key="runtime_inherited_primitive_release_v1";
 auto require=[](bool ok,const std::string&why){if(!ok)throw std::runtime_error("runtime primitive release: "+why);};
 if(!cfg.contains(key))return {{"schema","rinkfit.actual_runtime_primitive_release.v1"},{"requested",false},{"released_blocks",Json::array()},{"source_or_physical_values_changed",false}};
 const auto&request=cfg.at(key);require(cfg.contains("audit_expected_free_physical_blocks"),"an exact actual free-block whitelist is mandatory");require(cfg.contains("source_uv_capture_objective"),"release policy is scoped to explicit sourceUV recovery");
 const auto token=b.capture_state().token();const auto original=b.core.model.source_json;
 auto pin=[&](const Json&ref){const auto p=std::filesystem::u8path(ref.at("file").get<std::string>());require(p.is_absolute(),"evidence references must be absolute");runtime_primitive_release_detail_v1::pin(p,ref.at("sha256").get<std::string>());return p;};
 const auto cat_file=pin(request.at("catalog"));const auto cat=eventio::read_json(cat_file);require(cat.at("schema")=="rinkfit.current_fixed_unmeasured_ice_primitive_inventory.v1","unknown audited catalog schema");const auto catalog_model=eventio::read_json(pin(cat.at("model")));require(catalog_model.at("schema")==original.at("schema"),"catalog model schema differs from actual model");pin(cat.at("packet"));
 std::size_t covered=0;const auto protected_blocks=recovery_source_capture_detail::s01_dependencies(b.core,&covered);require(covered>0,"actual S01 dependency closure is empty");
 std::map<int,Json>catalog;for(const auto&record:cat.at("unmeasured_constant_primitive_blocks")){const int id=record.at("block_index");require(catalog.emplace(id,record).second,"duplicate catalog block");}
 std::map<int,Json>requested;for(const auto&record:request.at("blocks")){const int id=record.at("block_index");require(id>=0&&std::size_t(id)<b.core.model.blocks.size(),"block index outside actual registry");require(requested.emplace(id,record).second,"duplicate requested block");require(!protected_blocks.count(id),"requested block belongs to the actual S01 projection closure: "+b.core.model.blocks.at(id).name);require(catalog.count(id),"block is not an audited non-S01 initializer primitive");const auto&block=b.core.model.blocks.at(id);require(record.at("block_name")==block.name&&catalog.at(id).at("block_name")==block.name,"explicit block index/name mismatch");require(block.constant&&catalog.at(id).at("constant")==true&&catalog.at(id).at("unmeasured_initializer_provenance_found")==true,"primitive is not an inherited initializer constant");require(catalog_model.at("blocks").at(id)==original.at("blocks").at(id)&&catalog.at(id).at("values")==original.at("blocks").at(id).at("values"),"catalog target initializer descriptor/values changed");for(const auto&material:catalog.at(id).at("materials")){const auto mi=material.at("index").get<std::size_t>();require(catalog_model.at("materials").at(mi)==original.at("materials").at(mi)&&material.at("label")==b.core.model.materials.at(mi).label,"catalog target material descriptor changed");}for(const auto&name:cfg.value("temporary_runtime_fixed_physical_blocks",std::vector<std::string>{}))require(name!=block.name,"release contradicts explicit runtime freeze");for(const auto&prefix:cfg.value("temporary_runtime_fixed_physical_prefixes",std::vector<std::string>{}))require(block.name.rfind(prefix,0)!=0,"release contradicts prefix freeze");}
 require(!requested.empty(),"empty release request has no source-supported action");
 // Source material/position confidence alone never grants a world-instance ID.
 const auto gate_file=pin(request.at("source_support"));const auto gate=eventio::read_json(gate_file);require(gate.at("schema")=="rinkfit.typed_dense_source_instance_support_audit.v1","unknown actual instance-support schema");pin(gate.at("source_packet"));pin(gate.at("actual_review_consumer"));require(gate.at("paired_material_profile_can_grant_world_identity")==false&&gate.at("unreviewed_source_rows_default_to_confirmed")==false,"material-only or unreviewed rows were promoted to instance authority");for(const auto&ref:gate.at("evidence_refs"))pin(ref);
 const auto&doc=b.core.packet.source_json;require(doc.contains("dense_source_binding"),"release requires the actual dense source registry");const std::string source_sha=doc.contains("dense_numeric_auxiliary_overlay")?doc.at("dense_parent_packet").at("sha256").get<std::string>():b.core.packet.source_hash;require((gate.at("source_packet").at("sha256")==source_sha||gate.at("source_packet").at("sha256")==b.core.packet.source_hash),"instance support is not bound to the current qualified source packet");
 const auto&a=gate.at("arrays");for(const auto&entry:a.items())if(entry.value().is_object()&&entry.value().contains("file"))pin(entry.value());
 const auto ordinal=eventio::read_array<std::uint64_t>(gate_file.parent_path(),a.at("source_store_ordinal"),"<u8"),rows=eventio::read_array<std::uint64_t>(gate_file.parent_path(),a.at("packet_row"),"<u8");const auto state=eventio::read_array<std::uint8_t>(gate_file.parent_path(),a.at("instance_state"),"|u1"),kind=eventio::read_array<std::uint8_t>(gate_file.parent_path(),a.at("instance_support_kind"),"|u1");require(ordinal.size()==rows.size()&&state.size()==rows.size()&&kind.size()==rows.size(),"instance audit column lengths differ");
 const auto&reg=doc.at("dense_source_binding");pin(reg.at("source_store_ordinal"));const auto registry=eventio::read_array<std::uint64_t>(gate_file.parent_path(),reg.at("source_store_ordinal"),"<u8");const auto start=reg.at("row_start").get<std::size_t>();require(registry.size()==reg.at("count").get<std::size_t>(),"actual source registry shape");
 std::map<int,std::size_t>positive;std::set<std::uint64_t>seen;for(std::size_t k=0;k<rows.size();++k){const auto i=rows[k];require(seen.insert(i).second,"duplicate instance audit packet row");require(i>=start&&i<b.core.packet.rows.size()&&registry.at(std::size_t(i)-start)==ordinal[k],"instance audit original row/ordinal mismatch");require(state[k]<=1&&kind[k]<=3&&(state[k]?kind[k]>0:kind[k]==0),"instance state/support kind is inconsistent");const auto&r=b.core.packet.rows.at(i);if(!state[k]){require(!r.active,"audited source-instance unknown is still active; install its qualification delta before release");continue;}require(r.active,"positive support references an unknown/inactive source");const auto layout=r.layout(b.core.model);for(int id:layout.block_ids)if(requested.count(id))++positive[id];}
 std::size_t actual_confirmed=0;for(auto value:state)actual_confirmed+=value==1;require(actual_confirmed==gate.at("source_confirmed_rows").get<std::size_t>()&&rows.size()-actual_confirmed==gate.at("world_instance_unknown_rows").get<std::size_t>(),"instance audit counts differ from actual columns");
 for(const auto&entry:requested)require(positive[entry.first]>0,"no source-confirmed world-instance evidence for "+b.core.model.blocks.at(entry.first).name);
 Json released=Json::array();for(const auto&entry:requested){const int id=entry.first;auto&block=b.core.model.blocks.at(id);auto*x=block.values.data();require(problem.HasParameterBlock(x),"target is absent from the actual Ceres graph");install_joint_ceres_parameter_bounds(problem,block);problem.SetManifold(x,nullptr);if(!block.fixed_indices.empty())problem.SetManifold(x,new ceres::SubsetManifold(int(block.values.size()),block.fixed_indices));for(const auto&d:original.value("linear_control_manifolds",Json::array()))if(d.at("block").get<int>()==id)problem.SetManifold(x,new JointLinearControlManifold(d));problem.SetParameterBlockVariable(x);require(problem.ParameterBlockTangentSize(x)>0,"released primitive has no free original tangent");released.push_back({{"block_index",id},{"block_name",block.name},{"ambient_size",block.values.size()},{"tangent_size",problem.ParameterBlockTangentSize(x)},{"actual_positive_source_rows",positive[id]},{"serialized_constant_flag_preserved",block.constant}});}
 require(b.capture_state().token()==token&&b.core.model.source_json==original,"runtime release changed physical/source/auxiliary values");return {{"schema","rinkfit.actual_runtime_primitive_release.v1"},{"requested",true},{"catalog",request.at("catalog")},{"source_support",request.at("source_support")},{"S01_active_rows_in_actual_dependency_closure",covered},{"S01_dependency_blocks_excluded",protected_blocks.size()},{"released_blocks",released},{"original_bounds_and_manifolds_restored",true},{"source_or_physical_values_changed",false},{"source_accuracy_accepted",false}};
}
}
